import React, { useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";

const Hero = () => {
  const navigate = useNavigate();
  const canvasRef = useRef(null);
  const systemRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    let particles = [];
    const count = 60;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };

    resize();
    window.addEventListener("resize", resize);

    const center = {
      x: window.innerWidth * 0.75,
      y: window.innerHeight * 0.5,
    };

    for (let i = 0; i < count; i++) {
      particles.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        vx: (Math.random() - 0.5) * 0.6,
        vy: (Math.random() - 0.5) * 0.6,
        size: Math.random() * 2 + 1,
      });
    }

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      particles.forEach((p) => {
        // base movement
        p.x += p.vx;
        p.y += p.vy;

        // soft attraction toward orbit system (RIGHT SIDE)
        const dx = center.x - p.x;
        const dy = center.y - p.y;

        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < 300) {
          p.vx += dx * 0.0008;
          p.vy += dy * 0.0008;
        }

        // draw particle
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(56,189,248,0.7)";
        ctx.fill();
      });

      requestAnimationFrame(animate);
    };

    animate();

    return () => window.removeEventListener("resize", resize);
  }, []);

  return (
    <section className="hero">

      {/* 🌌 PARTICLE CANVAS */}
      <canvas ref={canvasRef} className="canvas" />

      <div className="container">

        {/* LEFT */}
        <div className="left">

          <p className="tag">WELCOME</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • System Thinker • Problem Solver
          </h2>

          <p className="desc">
            I design structured systems and build scalable applications where
            data, logic, and UI work as one connected ecosystem.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>

            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>

        </div>

        {/* RIGHT - ORBIT SYSTEM */}
        <div className="right">

          <div className="system" ref={systemRef}>

            <div className="ring ring1"></div>
            <div className="ring ring2"></div>

            <div className="center">
              <img
                src="https://i.ibb.co/4f1R9Zc/female-avatar.png"
                alt="avatar"
              />
              <p>Swetha A</p>
            </div>

            <div className="orbit">

              <div className="node n1">React</div>
              <div className="node n2">Java</div>
              <div className="node n3">Spring Boot</div>
              <div className="node n4">MySQL</div>
              <div className="node n5">Node.js</div>
              <div className="node n6">AI Systems</div>

            </div>

          </div>

        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 8%;
          overflow: hidden;
          position: relative;
        }

        /* 🌌 CANVAS */
        .canvas {
          position: absolute;
          top: 0;
          left: 0;
          width: 100%;
          height: 100%;
          z-index: 0;
        }

        .container {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 60px;
          width: 100%;
          align-items: center;
          position: relative;
          z-index: 2;
        }

        /* LEFT */
        .tag {
          font-size: 12px;
          letter-spacing: 3px;
          color: #64748b;
        }

        h1 {
          font-size: 62px;
        }

        .name {
          color: #38BDF8;
        }

        .role {
          font-size: 20px;
          color: #94a3b8;
        }

        .desc {
          margin-top: 18px;
          font-size: 16px;
          color: #cbd5e1;
          line-height: 1.7;
          max-width: 520px;
        }

        .buttons {
          margin-top: 30px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          font-weight: 600;
          border: 1px solid rgba(56,189,248,0.3);
        }

        .primary {
          background: #38BDF8;
          color: #0b1220;
        }

        .secondary {
          background: rgba(255,255,255,0.03);
          color: #38BDF8;
        }

        /* ORBIT */
        .system {
          position: relative;
          width: 360px;
          height: 360px;
          margin: auto;
        }

        .ring {
          position: absolute;
          border-radius: 50%;
          filter: drop-shadow(0 0 12px rgba(56,189,248,0.4));
        }

        .ring1 {
          width: 340px;
          height: 340px;
          top: 10px;
          left: 10px;
          border: 1px solid rgba(56,189,248,0.5);
          animation: spin 18s linear infinite;
        }

        .ring2 {
          width: 250px;
          height: 250px;
          top: 55px;
          left: 55px;
          border: 1px dashed rgba(56,189,248,0.3);
          animation: spinReverse 14s linear infinite;
        }

        @keyframes spin {
          100% { transform: rotate(360deg); }
        }

        @keyframes spinReverse {
          100% { transform: rotate(-360deg); }
        }

        /* CENTER */
        .center {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%,-50%);
          text-align: center;
        }

        .center img {
          width: 95px;
          height: 95px;
          border-radius: 50%;
          border: 2px solid rgba(56,189,248,0.5);
          box-shadow: 0 0 30px rgba(56,189,248,0.2);
        }

        .center p {
          font-size: 13px;
          color: #94a3b8;
        }

        /* ORBIT NODES */
        .orbit {
          position: absolute;
          width: 100%;
          height: 100%;
          animation: spin 10s linear infinite;
        }

        .node {
          position: absolute;
          padding: 7px 12px;
          border-radius: 18px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.25);
          font-size: 12px;
          color: #cbd5e1;
          white-space: nowrap;
        }

        .n1 { top: 0; left: 50%; transform: translateX(-50%); }
        .n2 { top: 50%; right: 0; transform: translateY(-50%); }
        .n3 { bottom: 0; left: 50%; transform: translateX(-50%); }
        .n4 { top: 50%; left: 0; transform: translateY(-50%); }
        .n5 { top: 15%; right: 20%; }
        .n6 { bottom: 15%; left: 20%; }

      `}</style>

    </section>
  );
};

export default Hero;
